/* Business, community and workspace views share existing account and save flows. */
let ecosystemModalEpoch=0;
const modalEpochBase=modal,closeEpochBase=closeModal;
modal=function(...args){ecosystemModalEpoch++;return modalEpochBase(...args)};
closeModal=function(){ecosystemModalEpoch++;return closeEpochBase()};
let ecosystem={businesses:[],myBusinesses:[],businessInvites:[],networks:{},rateRequests:[]},events=[],eventDetail=null,ecosystemCardBusiness='',calendarNavigatorOpen=false;
const ecosystemApiBase=api;
api=async function(path,method='GET',data){const r=await ecosystemApiBase(path,method,data);if(path==='/api/bootstrap'){ecosystem=await liveApi('/api/v3/ecosystem');events=(await liveApi('/api/v3/events')).events}return r};
async function refreshEcosystem(){ecosystem=await api('/api/v3/ecosystem');events=(await api('/api/v3/events')).events;render()}
function compactRoles(roles=[],limit=2){const selected=roles.slice(0,limit);return selected.map(r=>`<span class="tag">${esc(r)}</span>`).join('')+(roles.length>limit?`<button class="tag role-more" onclick="showAllRoles(this)" data-roles="${esc(JSON.stringify(roles))}">+${roles.length-limit} more</button>`:'')}
function showAllRoles(button){const rs=JSON.parse(button.dataset.roles||'[]');modal('Roles & categories',`<div class="row wrap gap8">${rs.map(r=>`<span class="tag">${esc(r)}</span>`).join('')}</div>`,'<button class="btn" onclick="closeModal()">Done</button>')}
const solidPaths={user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3Z"/>',feed:'<path d="M3 3h18v18H3Z"/><path fill="var(--surface)" d="M6 6h12v3H6Zm0 6h5v6H6Zm8 0h4v2h-4Zm0 4h4v2h-4Z"/>',brief:'<path d="M8 3h8v3h5v15H3V6h5Zm2 3h4V5h-4Z"/>',mail:'<path d="M2 5h20v14H2Z"/><path d="m3 6 9 7 9-7" fill="none" stroke="var(--surface)" stroke-width="2"/>',save:'<path d="M5 2h14v20l-7-5-7 5Z"/>',star:'<path d="m12 2 3.1 6.3 6.9 1-5 4.9 1.2 6.9-6.2-3.3-6.2 3.3L7 14.2l-5-4.9 6.9-1Z"/>',calendar:'<path d="M3 5h18v16H3Z"/><path fill="var(--surface)" d="M5 10h14v9H5Z"/><path d="M7 2v6m10-6v6" fill="none" stroke="currentColor" stroke-width="3"/>'};
const iconEcosystemBase=icon;
icon=function(name){return solidPaths[name]?`<span class="icon filled-icon" aria-hidden="true"><svg viewBox="0 0 24 24">${solidPaths[name]}</svg></span>`:iconEcosystemBase(name)};
renderApp=function(){const navs=[['feed','feed','Feed'],['discover','search','Discover'],...(account.profile?[['inbox','mail','Inbox'],['office','brief','Office']]:[]),['profile','user',account.profile?'My profile':'TAP IN']];const button=([v,i,l],mobile=false)=>`<button ${v==='office'?'data-office-nav':''} class="${mobile?'mobile-item':'nav'} ${view===v?'active':''}" aria-label="${l}" ${view===v?'aria-current="page"':''} onclick="${v==='profile'?"openProfile('me')":`nav('${v}')`}">${icon(i)}${mobile?'':`<span>${l}</span>`}${v==='inbox'&&threads.some(t=>t.unread)?'<span class="nav-notification"></span>':''}</button>`;const mobile=[['feed','feed','Feed'],['discover','search','Discover'],null,['office','brief','Office'],['inbox','mail','Inbox']];document.getElementById('app').innerHTML=`<header class="top"><button class="brand" aria-label="TAPPED IN feed" onclick="nav('feed')">TAPPED<span>IN</span></button><div class="topright"><button class="icon-btn" aria-label="Change theme" onclick="toggleTheme()">${icon(state.theme==='dark'?'sun':'moon')}</button><button class="top-profile avatar" aria-label="My profile" onclick="account.profile?openProfile('me'):location.assign('/login')">${account.profile&&me().photo?`<img src="${esc(me().photo)}" alt="${esc(me().name)}">`:account.profile?initials(me().name):icon('user')}</button><button class="icon-btn" aria-label="Settings" onclick="account.profile?nav('settings'):location.assign('/login')">${icon('settings')}</button></div></header><div class="shell"><aside class="side">${navs.map(n=>button(n)).join('')}<button class="btn primary" onclick="tapMenu()">${icon('plus')}Tap In</button><div class="sidefoot">${account.profile?`<button class="side-profile" onclick="openProfile('me')"><b>${esc(me().name)}</b><span>${esc(identityCategory(me()))}</span><span>${esc(me().city)}${me().country?', '+esc(me().country):''}</span></button>`:''}</div></aside><main class="main" id="main">${renderView()}</main><aside class="rail">${renderRail()}</aside></div><nav class="mobile-nav" aria-label="Main navigation">${mobile.map(n=>n?button(n,true):`<button class="mobile-tap" aria-label="Tap In, create a post" onclick="tapMenu()">${icon('plus')}</button>`).join('')}</nav>`;updateOfficeBadges()};
nav=function(v){if(v==='opportunities'){discoveryTab='brief';v='discover'}if(v==='bookings'){officeDesk='bookings';v='office'}view=v;route='app';render();window.scrollTo({top:0,behavior:'instant'})};
const coreRenderEcosystem=coreRender;
coreRender=function(){coreRenderEcosystem();if(view==='inbox'&&conversationId)document.querySelector('.main')?.classList.add('conversation-takeover')};
const openWorkEcosystem=openWork;
openWork=function(id){const p=state.posts.find(p=>p.id===id);if(p?.opp)return openOpportunity(p.opp);openWorkEcosystem(id);document.querySelectorAll('#modal .dialog-foot button').forEach(b=>{if(b.textContent.includes('Tap in to this work'))b.remove()});if(p)document.querySelector('#modal .dialog-body')?.insertAdjacentHTML('beforeend',postTags(p)+businessPostTags(p)+supportControl(p)+cardActions(p))};
const openOpportunityEcosystem=openOpportunity;
openOpportunity=function(id){openOpportunityEcosystem(id);const p=state.posts.find(p=>p.opp===id),o=state.opps.find(o=>o.id===id);if(p&&o)document.querySelector('#modal .dialog-body')?.insertAdjacentHTML('beforeend',cardActions({...o,...p,title:o.title})+supportControl(p))};
const reactEcosystem=react;
react=async function(...args){const dialog=document.getElementById('modal'),open=dialog.open,body=dialog.querySelector('.dialog-body'),id=args[1];await reactEcosystem(...args);if(open&&dialog.open&&dialog.querySelector('.dialog-body')===body&&state.posts.some(p=>p.id===id))openWork(id);else if(open&&dialog.open&&dialog.querySelector('.dialog-body')===body&&contributions.some(p=>p.id===id))openProfileContribution(id)};
function supportCount(id){return new Set(contributions.filter(c=>c.original===id).map(c=>c.by)).size}
function supportControl(p){const count=supportCount(p.id);return `<div class="post-support"><button class="text-btn" onclick="communityComposer('tap','${p.id}')">${icon('plus')} ${count} ${count===1?'person':'people'} tapped in</button><span class="meta">Appreciation, love & support</span></div>`}
function businessPostTags(p){return (p.businessTags||[]).map(t=>`<button class="tag" onclick="openBusiness('${t.business}')">${esc(t.name)} · ${esc(t.role)}${t.confirmed?'':' · Tagged'}</button>`).join('')}
const postCardEcosystem=postCard;
postCard=function(p){return postCardEcosystem(p).replace('</article>',businessPostTags(p)+supportControl(p)+'</article>')};
const contributionCardEcosystem=contributionCard;
contributionCard=function(p){return contributionCardEcosystem(p).replace('</article>',businessPostTags(p)+'</article>')};
function feedSuggestions(){const list=state.profiles.filter(p=>p.id!=='me'&&p.kind==='industry'&&!state.follows.includes(p.id)).slice(0,3);return list.length?`<section class="feed-suggestions"><div class="row between"><h3>People to discover</h3><button class="text-btn" onclick="nav('discover')">Discover</button></div><div class="suggestion-grid">${list.map(personCard).join('')}</div></section>`:''}
const feedEcosystem=renderFeed;
renderFeed=function(){const html=feedEcosystem(),start=html.indexOf('<article class="post"');if(start<0)return html+feedSuggestions();const end=html.indexOf('</article>',start);return html.slice(0,end+10)+feedSuggestions()+html.slice(end+10)};
personCard=function(p){return `<article class="person-card discovery-person"><button class="discovery-identity" onclick="openProfile('${p.id}')">${av(p)}<span><strong>${esc(p.name)}</strong><span class="meta">${esc(identityCategory(p))}</span><span class="meta">${esc(p.city)}${p.country?', '+esc(p.country):''}</span></span></button><div class="discovery-roles">${compactRoles(p.roles)}</div><button class="btn" onclick="toggleFollow('${p.id}')" aria-pressed="${state.follows.includes(p.id)}">${state.follows.includes(p.id)?'Following':'Follow'}</button></article>`};
const profileHeaderEcosystem=profileHeader;
profileHeader=function(p,own,work){return profileHeaderEcosystem(p,own,work).replace(highlightSection(p),'').replace(/<span class="tag">(?:Available for work|Booked)<\/span>/g,'').replace(/<div class="row wrap gap8 profile-roles">[\s\S]*?<\/div>/,`<div class="row wrap gap8 profile-roles">${compactRoles(p.roles,2)}</div>`)};
function profileNetwork(p,own){const n=ecosystem.networks[realMember(p.id)]||{affiliations:[],teams:[],agents:[]};return `<section class="profile-network"><div class="row between"><h3>Work & people</h3>${own?'<button class="text-btn" onclick="businessForm()">Add business</button>':''}</div>${n.affiliations.length?`<div class="network-list">${n.affiliations.map(a=>`<button class="network-chip" onclick="openBusiness('${a.business}')">${esc(a.name)}<small>${esc(a.role)}</small></button>`).join('')}</div>`:''}${n.teams.length?`<div class="network-list">${n.teams.map(t=>`<span class="network-chip">${esc(t.title)}<small>Team</small></span>`).join('')}</div>`:''}${n.agents.length?`<div class="network-list">${n.agents.map(a=>`<button class="network-chip" onclick="openProfile('${idMap({id:a.id},account.profile?.id,'me').id}')">${esc(a.name)}<small>Agent representation</small></button>`).join('')}</div>`:''}${own?'<div class="row wrap gap8"><button class="text-btn" onclick="workplaceForm()">Add workplace</button><button class="text-btn" onclick="grantAccess()">Add agent</button><button class="text-btn" onclick="setOfficeDesk(\'teams\')">Manage teams</button></div>':''}${!n.affiliations.length&&!n.teams.length&&!n.agents.length?'<p class="meta">Businesses, workplaces, teams and representation appear here when connected.</p>':''}</section>`}
renderProfile=function(){const p=person(activeProfile);if(!p)return '<div class="empty"><h3>Profile unavailable.</h3></div>';const own=p.id==='me',work=state.posts.filter(w=>w.type==='work'&&w.credits?.some(c=>c.id===p.id)).sort((a,b)=>b.date.localeCompare(a.date));const tabs=[['history','Work history'],['highlights','Highlights'],['moments','Moments'],['awards','Awards'],['rates','Rate card']];return `${profileHeader(p,own,work)}${profileNetwork(p,own)}<div class="tabs profile-tabs" role="tablist" aria-label="Profile sections">${tabs.map(([v,l])=>`<button class="tab ${profileTab===v?'active':''}" role="tab" aria-selected="${profileTab===v}" onclick="profileTab='${v}';render()">${l}</button>`).join('')}</div><section class="profile-panel">${profileTab==='highlights'?highlightSection(p):profileTab==='moments'?renderMoments(p,own):profileTab==='awards'?renderAwards(p,own):profileTab==='rates'?profileRates(p,own):`<div class="row between"><h3>Work history</h3>${own&&!fan()?'<button class="text-btn" onclick="startComposer(\'work\')">Add work</button>':''}</div>${work.map(w=>`<article class="history-item"><span class="meta">${fmt(w.date)} · ${esc(w.workType)}${w.paymentKind&&w.paymentKind!=='Paid'?' · '+esc(w.paymentKind):''}</span><h3>${esc(w.title)}</h3><div class="row wrap gap8">${compactRoles(w.credits.filter(c=>c.id===p.id).map(c=>c.role))}</div><button class="text-btn" onclick="openWork('${w.id}')">Open work</button></article>`).join('')||'<p class="meta">Confirmed work credits will appear here.</p>'}${(own?state.gigs.filter(g=>g.public):p.bookings||[]).map(g=>`<article class="history-item"><div class="row between wrap"><h3>${esc(g.title)}</h3><span class="meta">${fmt(g.date)}</span></div><p class="meta">${esc(g.paymentKind||'Paid')} · ${esc(g.partOf||g.participation||'Booking')}</p>${g.post?`<button class="text-btn" onclick="openWork('${g.post}')">Open completed work</button>`:''}</article>`).join('')}${contributions.filter(c=>c.by===realMember(p.id)).map(c=>`<article class="history-item"><span class="meta">${fmt(c.date)} · ${esc(c.contribution)}</span><h3>${esc(c.title)}</h3><button class="text-btn" onclick="openProfileContribution('${c.id}')">Open contribution</button></article>`).join('')}${renderProfileCalendar(p)}`}</section>`};
const calendarEcosystemBase=renderProfileCalendar;
renderProfileCalendar=function(p){let html=calendarEcosystemBase(p);html=html.replace(/<label class="calendar-jump">[\s\S]*?<\/label>/,'').replace(/<span aria-live="polite">([^<]+)<\/span>/,`<button class="calendar-month-select text-btn" aria-label="Choose month and year" onclick="toggleCalendarNavigator()">$1 ▾</button>`);if(calendarNavigatorOpen)html=html.replace('<div class="calendar-grid">',`<div class="calendar-month-picker"><label>Month<select onchange="setCalendarMonth(this.value,document.getElementById('calendar-year').value)">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${Number(profileCalendarMonth.slice(5))===i+1?'selected':''}>${new Date(2026,i,1).toLocaleDateString(undefined,{month:'long'})}</option>`).join('')}</select></label><label>Year<input id="calendar-year" type="number" min="1900" max="2100" value="${profileCalendarMonth.slice(0,4)}" onchange="setCalendarMonth(Number(profileCalendarMonth.slice(5)),this.value)"></label><button class="btn" onclick="toggleCalendarNavigator()">Done</button></div><div class="calendar-grid">`);return html};
function toggleCalendarNavigator(){calendarNavigatorOpen=!calendarNavigatorOpen;render()}
function setCalendarMonth(month,year){if(Number(year)<1900||Number(year)>2100||Number(month)<1||Number(month)>12)return;profileCalendarMonth=String(year)+'-'+String(month).padStart(2,'0');profileCalendarDay='';render()}
function profileRates(p,own){const available=ecosystem.networks[realMember(p.id)]?.rateAvailable;return own?`<section class="profile-rate-card"><div class="row between"><h3>Your offerings & prices</h3><button class="btn" onclick="designRateCard()">${state.rateCard?.items.length?'Edit':'Design'} rate card</button></div><p>Services and prices. Invoice and banking details stay in Office and company administration.</p>${state.rateCard?.items.length?rateCardMarkup(offeringsOnlyClient(state.rateCard),p.name,p.roles,p.photo):''}<label class="radio-row"><input type="checkbox" ${me().rateCardAvailable?'checked':''} onchange="setPersonalRatesAvailable(this.checked)">Allow people to request my rate card</label>${state.rateCard?.items.length?'<div class="row wrap gap8"><button class="btn" onclick="previewRateCard()">See rate card</button><button class="btn" onclick="shareRateCard()">Share card</button></div>':''}</section>`:`<div class="empty"><h3>${available?'Request their rate card.':'Rate card not available.'}</h3>${available?`<button class="btn primary" onclick="requestRateCard('${realMember(p.id)}')">Request rate card</button>`:'<p>Message this member to ask about their offerings.</p>'}</div>`}
function offeringsOnlyClient(c={}){return {title:c.title||'Rate card',intro:c.intro||'',style:'Minimal',deposit:0,notes:'',items:c.items||[]}}
async function setPersonalRatesAvailable(value){if(value&&!state.rateCard?.items.length){toast('Add offerings and prices first.');return render()}me().rateCardAvailable=value;try{await save();await refreshEcosystem()}catch(e){toast(e.message)}}
designRateCard=function(business=''){ecosystemCardBusiness=business;const card=business?ecosystem.myBusinesses.find(b=>b.id===business)?.card:state.rateCard;modal('Offerings & prices',`<label>Card title</label><input id="rate-title" maxlength="100" value="${esc(card?.title||'My rate card')}"><label>Introduction</label><textarea id="rate-intro" maxlength="300">${esc(card?.intro||'')}</textarea><div id="rate-items">${(card?.items?.length?card.items:[{}]).map(rateRow).join('')}</div><button class="text-btn" onclick="document.getElementById('rate-items').insertAdjacentHTML('beforeend',rateRow({}))">Add offering</button>${business?`<label class="radio-row"><input id="business-rate-available" type="checkbox" ${ecosystem.myBusinesses.find(b=>b.id===business)?.rateAvailable?'checked':''}>Allow requests for this rate card</label>`:''}<p>Invoice details are managed separately in Office and company administration.</p><div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveOfferingCard()">Save offerings</button>')};
async function saveOfferingCard(){const items=[...document.querySelectorAll('.rate-item-editor')].map(r=>({service:r.querySelector('.rate-service').value.trim(),price:Number(r.querySelector('.rate-price').value),unit:r.querySelector('.rate-unit').value,details:r.querySelector('.rate-details').value})),card={title:document.getElementById('rate-title').value.trim(),intro:document.getElementById('rate-intro').value,items,style:'Minimal',deposit:0,notes:''};if(!card.title||!items.length||items.some(i=>!i.service||i.price<0||!Number.isFinite(i.price)))return error('Add valid offerings and prices.');try{if(ecosystemCardBusiness){const b=ecosystem.myBusinesses.find(b=>b.id===ecosystemCardBusiness);await api('/api/v3/businesses/'+b.id,'POST',{action:'card',version:b.version,card,available:document.getElementById('business-rate-available').checked})}else{state.rateCard={...card,business:state.rateCard?.business||{}};await save()}await refreshEcosystem();closeModal();render()}catch(e){error(e.message)}}
const previewRateCardEcosystem=previewRateCard;
previewRateCard=function(){modal('Your offerings & prices',rateCardMarkup(offeringsOnlyClient(state.rateCard),me().name,me().roles,me().photo),'<button class="btn" onclick="closeModal()">Done</button><button class="btn" onclick="window.print()">Print / save PDF</button>')};
async function requestRateCard(member='',business=''){if(!requireAccount())return;try{await api('/api/v3/rate-requests','POST',{member,business});await refreshEcosystem();toast('Rate card requested. The reply will appear in Inbox.')}catch(e){toast(e.message)}}
function companyOptions(selected=''){return '<option value="">Personal / no company</option>'+ecosystem.myBusinesses.map(b=>`<option value="${b.id}" ${b.id===selected?'selected':''}>${esc(b.name)}</option>`).join('')}
function contextFields(prefix,d={}){return `<div class="grid2"><div><label>Business / company</label><select id="${prefix}-business">${companyOptions(d.business)}</select></div><div><label>Project</label><select id="${prefix}-project"><option value="">No project</option>${officeProjects.filter(p=>p.type!=='team'&&p.status!=='Invitation').map(p=>`<option value="${p.id}" ${d.project===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></div><div><label>Team</label><select id="${prefix}-team"><option value="">No team</option>${officeProjects.filter(p=>p.type==='team'&&p.status!=='Invitation').map(p=>`<option value="${p.id}" ${d.team===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></div><div><label>Work</label><select id="${prefix}-work"><option value="">No work</option>${state.posts.filter(p=>p.type==='work').map(p=>`<option value="${p.id}" ${d.work===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></div></div>`}
function captureContext(prefix){return Object.fromEntries(['business','project','team','work'].map(k=>[k,document.getElementById(prefix+'-'+k)?.value||'']))}
function businessForm(id=''){const b=ecosystem.myBusinesses.find(x=>x.id===id)||{};modal(id?'Business administration':'Add business / company',`<label>Business name</label><input id="biz-name" maxlength="100" value="${esc(b.name||'')}"><label>Category</label><select id="biz-category">${options(Object.keys(roleCategories),b.category||'Brand & Sponsor')}</select><label>City / town and country</label><input id="biz-city" list="biz-places" value="${esc([b.city,b.country].filter(Boolean).join(', '))}" placeholder="Johannesburg, South Africa"><datalist id="biz-places">${locationDirectory.map(l=>`<option value="${esc(l.city+', '+l.country)}">`).join('')}</datalist><label>About the business</label><textarea id="biz-bio" maxlength="400">${esc(b.bio||'')}</textarea>${id?billingFields('biz-billing',b.billing||{}):''}<p>This business appears on your profile as an owned company. Add co-owners and employees with accepted invitations.</p><div id="form-error" class="error"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveBusiness('${id}')">Save business</button>`)}
async function saveBusiness(id){const epoch=ecosystemModalEpoch,b=ecosystem.myBusinesses.find(b=>b.id===id),location=parseLocation(document.getElementById('biz-city').value),data={name:document.getElementById('biz-name').value,category:document.getElementById('biz-category').value,...location,bio:document.getElementById('biz-bio').value,...(id?{action:'details',version:b.version,billing:captureBilling('biz-billing')}: {})};try{const r=await api('/api/v3/businesses'+(id?'/'+id:''),'POST',data);await refreshEcosystem();if(epoch===ecosystemModalEpoch)openBusiness(r.business.id)}catch(e){error(e.message)}}
async function openBusiness(id){const epoch=ecosystemModalEpoch;try{const b=(await api('/api/v3/businesses/'+id)).business;if(epoch!==ecosystemModalEpoch)return;modal(b.name,`<p class="red">${esc(b.bio||'')}</p><p class="meta">${esc(b.category)} · ${esc(b.city)}${b.country?', '+esc(b.country):''}</p>${b.canManage?`<div class="row wrap gap8"><button class="btn" onclick="businessForm('${id}')">Company details</button><button class="btn" onclick="designRateCard('${id}')">Offerings & rate card</button><button class="btn" onclick="businessMemberForm('${id}')">Add co-owner / employee</button><button class="btn" onclick="newEvent('${id}')">Create event</button></div><h3>People</h3>${(b.members||[]).map(m=>`<div class="office-row"><span>${esc(contributionPerson(m.person)?.name||'Member')} · ${esc(m.role)} · ${esc(m.status)}</span>${m.status==='Requested'?`<button class="btn" onclick="businessRespond('${id}','${m.person}','Accepted')">Accept relationship</button>`:''}${m.status==='Accepted'?`<button class="text-btn" onclick="removeBusinessMember('${id}','${m.person}')">Remove</button>`:''}</div>`).join('')||'<p class="meta">Invite people to connect with this company.</p>'}`:b.rateAvailable?`<button class="btn primary" onclick="requestRateCard('','${id}')">Request business rate card</button>`:''}<div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Done</button>')}catch(e){toast(e.message)}}
function workplaceForm(){modal('Add a workplace or co-owned business',`<label>Business</label><select id="workplace-business"><option value="">Choose a business</option>${ecosystem.businesses.filter(b=>!ecosystem.networks[account.profile.id]?.affiliations.some(a=>a.business===b.id)).map(b=>`<option value="${b.id}">${esc(b.name)} · ${esc(b.city)}</option>`).join('')}</select><label>Your relationship</label><select id="workplace-role">${options(['Employee','Co-owner'])}</select><p>The company administrator confirms your relationship before it appears publicly.</p><div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="requestWorkplace()">Request relationship</button><button class="btn" onclick="businessForm()">Add my business instead</button>')}
async function requestWorkplace(){const id=document.getElementById('workplace-business').value;if(!id)return error('Choose a business.');const row=(await api('/api/v3/businesses/'+id)).business;try{await api('/api/v3/businesses/'+id,'POST',{action:'join',version:row.version??ecosystem.businesses.find(b=>b.id===id)?.version,role:document.getElementById('workplace-role').value});closeModal();await refreshEcosystem();toast('Relationship requested.')}catch(e){error(e.message)}}
function businessMemberForm(id){modal('Connect a company member',`<label>Person</label><select id="business-person">${state.profiles.filter(p=>p.id!=='me').map(p=>`<option value="${realMember(p.id)}">${esc(p.name)}</option>`).join('')}</select><label>Relationship</label><select id="business-role">${options(['Employee','Co-owner'])}</select><p>Co-owners can administer this company after accepting. Invitations appear in Inbox.</p><div id="form-error" class="error"></div>`,`<button class="btn" onclick="openBusiness('${id}')">Back</button><button class="btn primary" onclick="inviteBusinessMember('${id}')">Invite</button>`)}
async function inviteBusinessMember(id){try{const b=(await api('/api/v3/businesses/'+id)).business;await api('/api/v3/businesses/'+id,'POST',{action:'invite',version:b.version,person:document.getElementById('business-person').value,role:document.getElementById('business-role').value});await refreshEcosystem();openBusiness(id)}catch(e){error(e.message)}}
async function businessRespond(id,person,status){try{const b=(await api('/api/v3/businesses/'+id)).business;await api('/api/v3/businesses/'+id,'POST',{action:'respond',version:b.version,person,status});closeModal();await refreshEcosystem();toast('Business relationship '+status.toLowerCase()+'.')}catch(e){error(e.message)}}
async function removeBusinessMember(id,person){if(!confirm('Remove this business relationship?'))return;try{const b=(await api('/api/v3/businesses/'+id)).business;await api('/api/v3/businesses/'+id,'POST',{action:'remove-member',version:b.version,person});await refreshEcosystem();openBusiness(id)}catch(e){error(e.message)}}
const messagesEcosystemBase=renderMessages;
renderMessages=function(){const active=threads.find(t=>t.id===conversationId);if(!active)return `<div class="inbox-directory">${threads.map(t=>`<button class="conversation-row" onclick="selectConversation('${t.id}')"><div class="row"><span class="avatar">${initials(t.name)}</span><div><b>${esc(t.name)}</b><p>${esc(t.last||'Start the conversation')}</p></div>${t.unread?'<span class="unread-dot" aria-label="Unread messages"></span>':''}</div></button>`).join('')||'<div class="empty"><h3>No conversations yet.</h3><p>Start a conversation from a profile or send a message.</p></div>'}</div>`;const doc=new DOMParser().parseFromString(messagesEcosystemBase(),'text/html'),pane=doc.querySelector('.conversation-view');return `<section class="inbox-takeover"><button class="text-btn conversation-close" onclick="conversationId=null;render()">${icon('close')}Back to Inbox</button>${pane?.outerHTML||''}</section>`};
const inboxEventsEcosystem=inboxEvents;
inboxEvents=function(){return [...ecosystem.businessInvites.map(r=>({kind:'business',id:r.business+':'+r.person,title:r.name,detail:r.role+' · '+r.status,person:idMap({id:r.person===account.profile?.id?r.owner:r.person},account.profile?.id,'me').id,status:'Pending'})),...ecosystem.rateRequests.map(r=>({kind:'rate',id:r.id,title:r.name,detail:'Rate card · '+r.status,person:idMap({id:r.to===account.profile?.id?r.from:r.to},account.profile?.id,'me').id,status:r.status})),...inboxEventsEcosystem()]};
renderInbox=function(){if(conversationId)return renderMessages();const requests=inboxEvents();return `<div class="heading"><div class="row between"><h1>Inbox</h1><button class="btn primary" onclick="newMessage()">New message</button></div><p>Conversations, invitations and requests.</p></div><div class="inbox-directory">${requests.map(r=>`<button class="conversation-row inbox-event" onclick="openInboxEvent('${r.kind}','${r.id}')"><div class="row between"><strong>${esc(r.title)}</strong>${['Pending','Requested','Shared'].includes(r.status)?'<span class="unread-dot"></span>':''}</div><p>${esc(person(r.person)?.name||'Member')} · ${esc(r.detail)}</p></button>`).join('')}${threads.length?renderMessages():requests.length?'':renderMessages()}</div>`};
const openInboxEventEcosystem=openInboxEvent;
openInboxEvent=async function(kind,id){if(kind==='business'){const [business,person]=id.split(':'),r=ecosystem.businessInvites.find(r=>r.business===business&&r.person===person);return modal('Business relationship',`<h3>${esc(r.name)}</h3><p>${esc(r.role)} · ${esc(r.status)}</p><p>Accepting publishes this relationship on your profile. Co-owners can manage the company.</p>`,`<button class="btn" onclick="closeModal()">Done</button><button class="btn" onclick="businessRespond('${business}','${person}','Declined')">Decline</button><button class="btn primary" onclick="businessRespond('${business}','${person}','Accepted')">Accept</button>`)}if(kind==='rate'){const r=(await api('/api/v3/rate-requests/'+id)).request;return modal('Rate card request',r.card?rateCardMarkup(r.card,r.name):`<h3>${esc(r.name)}</h3><p>${esc(contributionPerson(r.from)?.name||'Member')} requested this rate card.</p><p>${esc(r.status)}</p>`,`<button class="btn" onclick="closeModal()">Done</button>${r.to===account.profile.id&&r.status==='Requested'?`<button class="btn" onclick="respondRateRequest('${id}','Declined')">Decline</button><button class="btn primary" onclick="respondRateRequest('${id}','Shared')">Share offerings & prices</button>`:''}`)}return openInboxEventEcosystem(kind,id)};
async function respondRateRequest(id,status){try{await api('/api/v3/rate-requests/'+id,'POST',{status});await refreshEcosystem();closeModal();render()}catch(e){error(e.message)}}
setOfficeDesk=function(desk){if(desk==='inbox')return nav('inbox');officeDesk=desk;officeProject=null;nav('office')};
const respondInviteEcosystem=respondInvitation;
respondInvitation=async function(...args){await respondInviteEcosystem(...args);view='inbox';render()};
const officeEcosystemBase=renderOffice;
renderOffice=function(){if(officeDesk==='inbox')return renderInbox();let html;if(officeDesk==='businesses')html=`<div class="heading"><div class="row between"><h1>Businesses</h1><button class="btn primary" onclick="businessForm()">Add business</button></div></div>${ecosystem.myBusinesses.map(b=>`<article class="office-row"><div><h3>${esc(b.name)}</h3><span class="meta">${b.canManage?'Administration':'Workplace'} · ${esc(b.category)}</span></div><button class="btn" onclick="openBusiness('${b.id}')">Open company</button></article>`).join('')}`;else if(officeDesk==='events')html=`<div class="heading"><div class="row between"><h1>Events</h1><button class="btn primary" onclick="newEvent()">Create event</button></div></div>${events.filter(e=>e.owner===account.profile.id||officeProjects.some(p=>p.id===e.project||p.id===e.team)).map(eventCard).join('')||'<p class="meta">Create an event or connect one to your project or team.</p>'}`;else if(officeDesk==='meetings')html=`<div class="heading"><h1>Meetings</h1><p>Meetings stay with their teams and projects.</p></div>${officeProjects.filter(p=>p.status!=='Invitation').map(p=>`<article class="office-row"><div><h3>${esc(p.title)}</h3>${(p.meetings||[]).map(m=>`<p>${fmt(m.date)} · ${esc(m.time)} · ${esc(m.title)}</p>`).join('')||'<p class="meta">No meetings scheduled.</p>'}</div><button class="btn" onclick="officeTab='meetings';openProject('${p.id}')">Open meetings</button></article>`).join('')}`;else html=officeEcosystemBase();const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelectorAll('.office-desk-tabs button').forEach(b=>{if(b.textContent.trim().startsWith('Inbox'))b.remove()});const tabs=doc.querySelector('.office-desk-tabs');if(tabs)tabs.insertAdjacentHTML('beforeend',`<button onclick="setOfficeDesk('businesses')">Businesses</button><button onclick="setOfficeDesk('events')">Events</button><button onclick="setOfficeDesk('meetings')">Meetings</button>`);else doc.body.insertAdjacentHTML('afterbegin',`<div class="office-tabs office-desk-tabs">${[['projects','Projects'],['teams','Teams'],['bookings','Bookings'],['businesses','Businesses'],['events','Events'],['meetings','Meetings'],['contacts','Contacts']].map(([v,l])=>`<button class="${officeDesk===v?'active':''}" onclick="setOfficeDesk('${v}')">${l}</button>`).join('')}</div>`);doc.querySelectorAll('button').forEach(b=>{if(b.textContent.trim()==='Approvals')b.textContent='Budget'});return doc.body.innerHTML};
const tapMenuEcosystem=tapMenu;
tapMenu=function(){tapMenuEcosystem();document.querySelector('#modal .stack')?.insertAdjacentHTML('beforeend','<button class="btn" onclick="newEvent()">Create event</button>')};
function eventCard(e){return `<article class="event-card"><div><span class="meta">${fmt(e.date)}${e.time?' · '+esc(e.time):''} · ${esc(e.status)}</span><h3>${esc(e.title)}</h3><p>${esc(e.city)}${e.country?', '+esc(e.country):''} · ${esc(e.location)}</p><span class="meta">${e.going} going${e.attendance?' · '+esc(e.attendance):''}</span></div><button class="btn" onclick="openEvent('${e.id}')">Open event</button></article>`}
function newEvent(business=''){if(!requireAccount())return;contributionPresentation={image:'',imageOrientation:'landscape'};modal('Create event',`<label>Event name</label><input id="event-title" maxlength="120"><label>About the event</label><textarea id="event-description" maxlength="2000"></textarea><div class="grid2"><div><label>Date</label><input id="event-date" type="date"></div><div><label>Time (at the venue)</label><input id="event-time" type="time"></div></div><label>Venue / place</label><input id="event-location" maxlength="150"><label>City / town, country</label><input id="event-city" list="event-places" value="${esc([me().city,me().country||'South Africa'].join(', '))}"><datalist id="event-places">${locationDirectory.map(l=>`<option value="${esc(l.city+', '+l.country)}">`).join('')}</datalist>${contextFields('event',{business,project:officeProject?.type!=='team'?officeProject?.id:'',team:officeProject?.type==='team'?officeProject.id:''})}<label>Visibility</label><select id="event-visibility">${options(['Public','Private'])}</select>${postImageFields({},'contribution')}<div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="publishNewEvent()">Create event</button>')}
async function publishNewEvent(){if(uploadingPostImage)return error('Wait for the image upload.');try{const r=await api('/api/v3/events','POST',{title:document.getElementById('event-title').value,description:document.getElementById('event-description').value,date:document.getElementById('event-date').value,time:document.getElementById('event-time').value,location:document.getElementById('event-location').value,...parseLocation(document.getElementById('event-city').value),...captureContext('event'),image:contributionPresentation.image,visibility:document.getElementById('event-visibility').value});await refreshEcosystem();openEvent(r.event.id)}catch(e){error(e.message)}}
async function openEvent(id){const epoch=ecosystemModalEpoch;try{
 const r=await api('/api/v3/events/'+id),e=r.event;if(epoch!==ecosystemModalEpoch)return;eventDetail=e;
 const offers=e.canManage?`<h3>Service offers</h3>${r.offers.map(o=>`<article class="office-row"><div><b>${esc(contributionPerson(o.person)?.name||'Member')}</b><p>${esc(o.title)} · ${esc(o.paymentKind)}${o.paymentKind==='Paid'?' · '+money(o.price):''} · ${esc(o.status)}</p></div>${o.status==='Offered'?`<div class="row wrap gap8"><button class="btn" onclick="eventAction({action:'offer-response',offer:'${o.id}',status:'Accepted'})">Accept offer</button><button class="text-btn" onclick="eventAction({action:'offer-response',offer:'${o.id}',status:'Declined'})">Decline</button></div>`:o.status==='Accepted'?`<button class="btn" onclick="bookEventService('${o.id}')">Connect booking</button>`:''}</article>`).join('')||'<p class="meta">Services offered by members appear here.</p>'}`:r.offers.length?'<h3>Your offers</h3>'+r.offers.map(o=>`<p>${esc(o.title)} · ${esc(o.status)}</p>`).join(''):'';
 modal(e.title,`${e.image?`<img class="event-cover" src="${esc(e.image)}" alt="">`:''}<p>${esc(e.description)}</p><p>${fmt(e.date)} ${esc(e.time||'')} · ${esc(e.location)} · ${esc(e.city)}</p><p>${e.going??e.attendees?.filter(a=>a.status==='Going').length??0} going</p><div class="row wrap gap8"><button class="btn" onclick="eventAction({action:'attendance',status:'Going'})">Going</button><button class="btn" onclick="eventAction({action:'attendance',status:'Not going'})">Not going</button><button class="btn" onclick="eventOfferForm()">Offer a service</button><button class="btn" onclick="shareEvent('${id}')">${icon('share')}Share</button>${e.canManage?'<button class="btn" onclick="editEventForm()">Manage event</button>':''}</div>${offers}<div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Done</button>');
 }catch(e){toast(e.message)}}
async function eventAction(data){if(!requireAccount())return;try{await api('/api/v3/events/'+eventDetail.id,'POST',{...data,version:eventDetail.version});events=(await api('/api/v3/events')).events;await openEvent(eventDetail.id);render()}catch(e){error(e.message)}}
function eventOfferForm(){modal('Offer a service',`<label>Your offering</label><input id="event-service-title" maxlength="200"><label>Payment type</label><select id="event-service-kind">${options(['Paid','Pro bono','Passion project'])}</select><label>Price (ZAR)</label><input id="event-service-price" type="number" min="0" step="0.01" value="0"><p>Pro bono and passion-project offers have no fee. Agree the scope before confirming work.</p><div id="form-error" class="error"></div>`,`<button class="btn" onclick="openEvent('${eventDetail.id}')">Back</button><button class="btn primary" onclick="saveEventOffer()">Send offering</button>`)}
async function saveEventOffer(){await eventAction({action:'offer',title:document.getElementById('event-service-title').value,paymentKind:document.getElementById('event-service-kind').value,price:Number(document.getElementById('event-service-price').value)})}
function editEventForm(){const e=eventDetail;modal('Manage event',`<label>Name</label><input id="event-title" value="${esc(e.title)}"><label>Description</label><textarea id="event-description">${esc(e.description)}</textarea><label>Date</label><input id="event-date" type="date" value="${e.date}"><label>Time (at the venue)</label><input id="event-time" type="time" value="${e.time}"><label>Location</label><input id="event-location" value="${esc(e.location)}"><label>Status</label><select id="event-status">${options(['Scheduled','Cancelled'],e.status)}</select><div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveEventDetails()">Save event</button>')}
async function saveEventDetails(){await eventAction({action:'details',title:document.getElementById('event-title').value,description:document.getElementById('event-description').value,date:document.getElementById('event-date').value,time:document.getElementById('event-time').value,location:document.getElementById('event-location').value,status:document.getElementById('event-status').value})}
function shareEvent(id){const link=location.origin+'/feed#event/'+id,e=events.find(e=>e.id===id);modal('Share event',`${shareInvitationLinks(link,e?.title||'Tap in to this event')}<label>Event link</label><input id="event-share-link" readonly value="${esc(link)}">`,'<button class="btn" onclick="closeModal()">Done</button><button class="btn primary" onclick="copyEventLink()">Copy link</button>')}
async function copyEventLink(){try{await navigator.clipboard.writeText(document.getElementById('event-share-link').value);toast('Event link copied.')}catch{document.getElementById('event-share-link').select()}}
function bookEventService(id){const e=eventDetail,o=e.services.find(s=>s.id===id);bookingRequest(idMap({id:o.person},account.profile.id,'me').id);document.getElementById('book-title').value=e.title+' / '+o.title;document.getElementById('book-date').value=e.date;document.getElementById('book-fee').value=o.price;document.getElementById('book-note').value=o.title;document.getElementById('book-payment-kind').value=o.paymentKind;document.getElementById('booking-event').value=e.id;const location=document.getElementById('book-location');location.insertAdjacentHTML('beforeend',`<option selected value="${esc(e.location)}">${esc(e.location)}</option>`)}
const discoverEcosystemBase=renderDiscover;
renderDiscover=function(){let html=discoverEcosystemBase();const doc=new DOMParser().parseFromString(html,'text/html'),tabs=doc.querySelector('.tabs');tabs?.insertAdjacentHTML('beforeend',`<button class="tab ${discoveryTab==='events'?'active':''}" onclick="discoveryTab='events';render()">Events</button>`);if(discoveryTab==='events'){doc.querySelector('#discover-results').innerHTML=events.filter(e=>searchMatches([e.title,e.description,e.city,e.country,e.location])).map(eventCard).join('')||'<div class="empty"><h3>No matching events yet.</h3></div>';doc.querySelector('.discovery-actions')?.insertAdjacentHTML('beforeend',account.profile?'<button class="btn" onclick="newEvent()">Create event</button>':'')}return doc.body.innerHTML};
const discoverResultsEcosystem=discoverResults;
discoverResults=function(){if(discoveryTab==='events')return events.filter(e=>searchMatches([e.title,e.description,e.city,e.country,e.location])).map(eventCard).join('')||'<div class="empty"><h3>No matching events.</h3></div>';return discoverResultsEcosystem()};
const newProjectEcosystem=newProject;
newProject=function(team=false){newProjectEcosystem(team);document.getElementById('project-title')?.insertAdjacentHTML('afterend',`<label>Business / company (optional)</label><select id="project-business">${companyOptions()}</select>${team?'<label class="radio-row"><input id="team-profile-visible" type="checkbox">Show this team on members’ profiles</label>':''}`);enhanceSearches()};
const createProjectEcosystem=createProject;
createProject=async function(){const previous=api;const company=document.getElementById('project-business')?.value||'',publicTeam=!!document.getElementById('team-profile-visible')?.checked;api=async function(path,method,data){return previous(path,method,path==='/api/v3/office'&&method==='POST'?{...data,project:{...data.project,business:company,publicTeam}}:data)};try{return await createProjectEcosystem()}finally{api=previous}};
const projectOfficeEcosystem=projectOffice;
projectOffice=function(){if(!officeProject)return projectOfficeEcosystem();const p=officeProject;let html;if(officeTab==='meetings')html=`<div class="office-main"><button class="text-btn" onclick="officeProject=null;render()">All workspaces</button><h2>${esc(p.title)}</h2>${workspaceTabs()}<div class="row between"><h3>Meetings</h3><button class="btn primary" onclick="meetingForm()">Add meeting</button></div>${(p.meetings||[]).map(m=>`<article class="office-row"><div><h3>${esc(m.title)}</h3><p>${fmt(m.date)} · ${esc(m.time)} SAST</p><p>${esc(m.agenda)}</p><p class="meta">${m.people.map(id=>esc(contributionPerson(id)?.name||'Member')).join(', ')}</p></div><button class="btn" onclick="meetingForm('${m.id}')">Open / edit</button></article>`).join('')||'<p class="meta">Schedule a discussion with your project or team.</p>'}</div>`;else if(officeTab==='budget'||officeTab==='approvals')html=budgetWorkspace();else if(officeTab==='events')html=`<div class="office-main"><h2>${esc(p.title)}</h2>${workspaceTabs()}<button class="btn primary" onclick="newEvent('${p.business||''}')">Create linked event</button>${events.filter(e=>e.project===p.id||e.team===p.id).map(eventCard).join('')}</div>`;else{const doc=new DOMParser().parseFromString(projectOfficeEcosystem(),'text/html'),tabs=doc.querySelector('.office-tabs');if(tabs)tabs.outerHTML=workspaceTabs();html=doc.body.innerHTML}if(p.type==='team'&&p.owner===account.profile.id&&officeTab==='overview')html+=`<section class="settings-block"><h3>Team profiles</h3><label class="radio-row"><input type="checkbox" ${p.publicTeam?'checked':''} onchange="officeAction({action:'team-visibility',public:this.checked}).then(refreshEcosystem)">Show this team on members’ profiles</label></section>`;return `<p class="workspace-company meta">${p.business?'Company: '+esc(ecosystem.businesses.find(b=>b.id===p.business)?.name||'Business'):p.type==='team'?'Independent team':'Personal project'}${p.team?' · Team: '+esc(officeProjects.find(t=>t.id===p.team)?.title||'Connected team'):''}</p>`+html};
function workspaceTabs(){return `<div class="office-tabs workspace-tabs">${[['overview','Overview'],['tasks','Tasks'],['meetings','Meetings'],['events','Events'],['documents','Documents'],['assets','Assets'],['invoices','Invoices'],['team','Team'],['chat','Chat'],['budget','Budget']].map(([t,l])=>`<button class="${officeTab===t||t==='budget'&&officeTab==='approvals'?'active':''}" onclick="setOfficeTab('${t}')">${l}</button>`).join('')}</div>`}
function meetingForm(id=''){const p=officeProject,m=p.meetings?.find(m=>m.id===id)||{};modal(id?'Manage meeting':'Add meeting',`<label>Title</label><input id="meeting-title" maxlength="120" value="${esc(m.title||'')}"><div class="grid2"><div><label>Date</label><input id="meeting-date" type="date" value="${m.date||''}"></div><div><label>Time (SAST)</label><input id="meeting-time" type="time" value="${m.time||'09:00'}"></div></div><label>Agenda</label><textarea id="meeting-agenda" maxlength="3000">${esc(m.agenda||'')}</textarea><label>Participants</label><input type="search" aria-label="Search meeting participants" placeholder="Search people" oninput="document.querySelectorAll('.meeting-person').forEach(l=>l.hidden=!l.textContent.toLowerCase().includes(this.value.toLowerCase()))"><div class="meeting-people">${[p.owner,...p.members.filter(m=>m.status==='Accepted').map(m=>m.person)].map(person=>`<label class="radio-row meeting-person"><input type="checkbox" name="meeting-person" value="${person}" ${(m.people||[account.profile.id]).includes(person)?'checked':''}>${esc(contributionPerson(person)?.name||'Member')}</label>`).join('')}</div><div id="form-error" class="error"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button>${id?`<button class="btn" onclick="removeMeeting('${id}')">Remove meeting</button>`:''}<button class="btn primary" onclick="saveMeeting('${id}')">Save meeting</button>`)}
async function workspaceMutation(kind,data){try{const r=await api('/api/v3/'+kind+'/'+officeProject.id,'POST',{...data,version:officeProject.version});officeProject=r.project;const i=officeProjects.findIndex(p=>p.id===officeProject.id);if(i>=0)officeProjects[i]=officeProject;closeModal();render();return true}catch(e){error(e.message);toast(e.message);return false}}
async function saveMeeting(id){await workspaceMutation('meetings',{meeting:id,title:document.getElementById('meeting-title').value,date:document.getElementById('meeting-date').value,time:document.getElementById('meeting-time').value,agenda:document.getElementById('meeting-agenda').value,people:[...document.querySelectorAll('input[name=meeting-person]:checked')].map(e=>e.value)})}
async function removeMeeting(id){if(confirm('Remove this meeting?'))await workspaceMutation('meetings',{action:'delete',meeting:id})}
function budgetManager(){return officeProject.owner===account.profile.id||memberAccess.some(m=>m.owner===officeProject.owner&&m.approve)||ecosystem.myBusinesses.some(b=>b.id===officeProject.business&&b.canManage)}
function budgetWorkspace(){const p=officeProject,manager=budgetManager(),records=(p.transactions||[]).filter(t=>manager||t.person===account.profile.id),income=records.filter(t=>t.direction==='Income').reduce((s,t)=>s+t.amount,0),spending=records.filter(t=>t.direction==='Expense').reduce((s,t)=>s+t.amount,0),paid=records.filter(t=>t.direction==='Income'&&t.paid).reduce((s,t)=>s+t.amount,0);return `<div class="office-main"><h2>${esc(p.title)}</h2>${workspaceTabs()}<div class="finance-metrics"><div><small>Recorded income</small><strong>${money(income)}</strong></div><div><small>Recorded spending</small><strong>${money(spending)}</strong></div><div><small>Income received</small><strong>${money(paid)}</strong></div><div><small>Net recorded</small><strong>${money(income-spending)}</strong></div></div><p class="meta">Records of agreed and received amounts; this does not transfer money.</p><div class="row wrap gap8"><button class="btn primary" onclick="officeForm('proposal')">Propose itemized budget</button><button class="btn" onclick="transactionForm()">Record income / spending</button></div><h3>Approved budget · ${money(p.budget)}</h3>${(p.budgetItems||[]).map((item,index)=>`<article class="office-row"><div><strong>${esc(item.description)}</strong><p>${item.quantity} × ${money(item.rate)} · ${money(item.quantity*item.rate)}</p><p class="meta">${item.assignee?'Assigned to '+esc(contributionPerson(item.assignee)?.name||'Member'):'Unassigned'}</p></div>${manager?`<button class="btn" onclick="assignBudgetForm(${index})">Assign item</button>`:''}</article>`).join('')||'<p class="meta">Approve a proposal to establish the itemized budget.</p>'}<h3>Income & spending records</h3>${records.map(t=>`<article class="office-row"><div><strong>${esc(t.title)}</strong><p>${esc(t.direction)} · ${money(t.amount)} · ${fmt(t.date)}</p><small>${esc(contributionPerson(t.person)?.name||'Member')} · ${t.paid?'Received / paid':'Outstanding'}</small></div>${manager||t.by===account.profile.id?`<button class="btn" onclick="workspaceMutation('finance',{action:'paid',transaction:'${t.id}',paid:${!t.paid}})">${t.paid?'Mark outstanding':'Mark received / paid'}</button>`:''}</article>`).join('')||'<p class="meta">Record pro bono or passion projects with zero fees; keep paid income and spending distinct.</p>'}<h3>Budget proposals</h3>${p.approvals.map(a=>`<article class="office-row"><div><strong>${money(a.budget)} · ${esc(a.status)}</strong><p>${esc(a.scope)}</p>${budgetItemsMarkup(a.items||[])}</div>${manager&&a.status==='Pending'?`<div class="row wrap gap8"><button class="btn primary" onclick="workspaceMutation('finance',{action:'approve',approval:'${a.id}'})">Approve budget</button><button class="btn" onclick="workspaceMutation('finance',{action:'decline',approval:'${a.id}'})">Decline</button></div>`:''}</article>`).join('')}</div>`}
function assignBudgetForm(index){modal('Assign budget item',`<label>Teammate</label><select id="budget-assignee">${officeMemberOptions(officeProject.budgetItems[index]?.assignee||'')}</select><div id="form-error" class="error"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="workspaceMutation('finance',{action:'assign',index:${index},person:document.getElementById('budget-assignee').value})">Assign</button>`)}
function transactionForm(){modal('Record income or spending',`<label>Record description</label><input id="ledger-title" maxlength="200"><div class="grid2"><div><label>Direction</label><select id="ledger-direction">${options(['Income','Expense'])}</select></div><div><label>Amount (ZAR)</label><input id="ledger-amount" type="number" min="0" step="0.01"></div></div><label>Date</label><input id="ledger-date" type="date" value="${localDate()}"><label>Person</label><select id="ledger-person">${budgetManager()?officeMemberOptions(account.profile.id):`<option value="${account.profile.id}">${esc(me().name)}</option>`}</select><label>Budget item (optional)</label><select id="ledger-item"><option value="">General income / expense</option>${(officeProject.budgetItems||[]).map(i=>`<option value="${i.id||''}">${esc(i.description)}</option>`).join('')}</select><label class="radio-row"><input id="ledger-paid" type="checkbox">Already received / paid</label><div id="form-error" class="error"></div>`,'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveTransaction()">Save record</button>')}
async function saveTransaction(){await workspaceMutation('finance',{action:'transaction',title:document.getElementById('ledger-title').value,direction:document.getElementById('ledger-direction').value,amount:Number(document.getElementById('ledger-amount').value),date:document.getElementById('ledger-date').value,person:document.getElementById('ledger-person').value,item:document.getElementById('ledger-item').value,paid:document.getElementById('ledger-paid').checked})}
const profileActivityEcosystem=publicProfileActivity;
publicProfileActivity=function(p){const activity=profileActivityEcosystem(p);activity.push(...events.filter(e=>e.owner===realMember(p.id)||p.id==='me'&&e.attendance==='Going').map(e=>({date:e.date,title:e.title,event:e.id})));if(p.id==='me')for(const workspace of officeProjects)for(const m of workspace.meetings||[])activity.push({date:m.date,title:m.title+' · '+m.time,project:workspace.id,private:true});return activity};
const openProfileDayEcosystem=openProfileDay;
openProfileDay=function(date){openProfileDayEcosystem(date);const p=person(activeProfile);for(const event of events.filter(e=>e.date===date&&(e.owner===realMember(p.id)||p.id==='me'&&e.attendance==='Going')))document.querySelector('#modal .dialog-body')?.insertAdjacentHTML('beforeend',`<button class="btn" onclick="openEvent('${event.id}')">Open ${esc(event.title)}</button>`)};
function businessTagFields(tags=[]){return `<section class="business-tag-editor"><label>Business / company contributors</label><div id="business-tags">${tags.map(businessTagRow).join('')}</div><button class="text-btn" onclick="document.getElementById('business-tags').insertAdjacentHTML('beforeend',businessTagRow({}));enhanceSearches()">Add / tag business & role</button></section>`}
function businessTagRow(t={}){return `<div class="business-tag-row"><select class="post-business" aria-label="Tagged business"><option value="">Choose a business</option>${ecosystem.businesses.map(b=>`<option value="${b.id}" ${b.id===t.business?'selected':''}>${esc(b.name)}</option>`).join('')}</select><input class="post-business-role" aria-label="Business contribution" maxlength="80" value="${esc(t.role||'')}" placeholder="Sponsor, production, venue…"><button aria-label="Remove business tag" onclick="this.parentElement.remove()">${icon('close')}</button></div>`}
function captureBusinessTags(){return [...document.querySelectorAll('.business-tag-row')].map(r=>({business:r.querySelector('.post-business').value,role:r.querySelector('.post-business-role').value.trim()})).filter(t=>t.business||t.role)}
const drawComposerEcosystem=drawComposer;
drawComposer=function(){drawComposerEcosystem();if(composerStep===1){document.getElementById('compose-description')?.insertAdjacentHTML('afterend',businessTagFields(composerData.businessTags||[])+`<label>Type of work</label><select id="compose-payment-kind" onchange="if(this.value!=='Paid'){const el=document.getElementById('compose-paid');if(el)el.value='0'}">${options(['Paid','Pro bono','Passion project'],composerData.paymentKind||'Paid')}</select>`);enhanceSearches()}};
const captureComposerEcosystem=captureComposer;
captureComposer=function(){captureComposerEcosystem();if(composerStep===1){composerData.businessTags=captureBusinessTags();composerData.paymentKind=document.getElementById('compose-payment-kind')?.value||'Paid'}};
const editPostEcosystem=editPost;
editPost=function(id){editPostEcosystem(id);const p=state.posts.find(p=>p.id===id)||state.posts.find(p=>p.opp===id);if(p&&composerData){composerData.businessTags=p.businessTags||[];composerData.paymentKind=p.paymentKind||'Paid';drawComposer()}};
const communityComposerEcosystem=communityComposer;
communityComposer=function(...args){communityComposerEcosystem(...args);document.getElementById('tap-description')?.insertAdjacentHTML('afterend',businessTagFields());enhanceSearches()};
const publishContributionEcosystem=publishContribution;
publishContribution=async function(type){contributionPresentation.businessTags=captureBusinessTags();return publishContributionEcosystem(type)};
const bookingEcosystem=bookingRequest;
bookingRequest=function(id){bookingEcosystem(id);document.getElementById('book-note')?.insertAdjacentHTML('beforebegin',`<label>Payment type</label><select id="book-payment-kind" onchange="document.getElementById('book-fee').value=this.value==='Paid'?'':'0'">${options(['Paid','Pro bono','Passion project'])}</select>${contextFields('booking')}<label>Event (optional)</label><select id="booking-event"><option value="">No event</option>${events.map(e=>`<option value="${e.id}">${esc(e.title)}</option>`).join('')}</select>`);enhanceSearches()};
const editGigEcosystem=editGig;
editGig=function(id,booking){editGigEcosystem(id,booking);const g=state.gigs.find(g=>g.id===id)||booking||{};document.getElementById('gig-amount')?.insertAdjacentHTML('afterend',`<label>Payment type</label><select id="gig-payment-kind" onchange="if(this.value!=='Paid')document.getElementById('gig-amount').value=0">${options(['Paid','Pro bono','Passion project'],g.paymentKind||'Paid')}</select>`);document.getElementById('gig-partof')?.insertAdjacentHTML('afterend',contextFields('gig-link',g)+`<label>Event</label><select id="gig-link-event"><option value="">No event</option>${events.map(e=>`<option value="${e.id}" ${g.event===e.id?'selected':''}>${esc(e.title)}</option>`).join('')}</select>`);enhanceSearches()};
const bookingsEcosystem=renderBookings;
renderBookings=function(){let html=bookingsEcosystem();for(const g of state.gigs)html=html.replace(esc(g.title)+'</h3>',esc(g.title)+`</h3><span class="tag">${esc(g.paymentKind||'Paid')}</span>`);return html};
const renderEcosystemBase=render;
render=function(){renderEcosystemBase();if(view==='inbox'&&conversationId)document.querySelector('.main')?.classList.add('conversation-takeover');document.querySelectorAll('.available-for-work').forEach(el=>el.remove())};
const siteTopEcosystem=siteTop;
siteTop=function(){const doc=new DOMParser().parseFromString(siteTopEcosystem(),'text/html');doc.querySelectorAll('a[href="/login"]').forEach(a=>a.remove());doc.querySelectorAll('a[href="/signup"],a[href="/app"]').forEach(a=>a.textContent='TAP IN');return doc.body.innerHTML};
const landingEcosystemBase=renderLanding;
renderLanding=function(){let html=landingEcosystemBase().replace(/>Log in<\/a>/gi,'>TAP IN</a>');return html.replace('<section class="home-section home-how"',`<section class="home-section home-connected-feature"><div class="eyebrow">YOUR PEOPLE. YOUR BUSINESSES. YOUR NEXT MOVE.</div><h2>RUN THE WORK.<br>KEEP IT CONNECTED.</h2><div class="home-agent-grid"><article><h3>People and companies</h3><p>Add the businesses you own, co-own or work at. Connect your teams, agent and work on one professional profile.</p></article><article><h3>Offerings and opportunities</h3><p>Showcase your highlights and make personal or business rate cards available to request. Offer services, show support and get credited.</p></article><article><h3>Events and collaboration</h3><p>Create events, offer your services, show you’re going and keep event work with its teams and projects.</p></article><article><h3>Meetings and the money</h3><p>Organise meetings, assign budget items and record income and spending. Keep paid, pro bono and passion projects distinct.</p></article></div><a class="btn primary" href="/signup">TAP IN</a></section><section class="home-section home-how"`)};
const startEcosystemBase=startApp;
startApp=async function(){await startEcosystemBase();const m=location.hash.match(/^#event\/([A-Za-z0-9_-]+)$/);if(m)await openEvent(m[1]);if(location.hash==='#inbox')nav('inbox')};
window.addEventListener('hashchange',()=>{const m=location.hash.match(/^#event\/([A-Za-z0-9_-]+)$/);if(m)openEvent(m[1])});

const rateMarkupEcosystem=rateCardMarkup;
rateCardMarkup=function(card,name,rs=[],photo=''){let html=rateMarkupEcosystem(offeringsOnlyClient(card),name,rs.slice(0,2),photo);if(rs.length>2)html=html.replace(rs.slice(0,2).map(esc).join(' / '),rs.slice(0,2).map(esc).join(' / ')+' · +'+(rs.length-2)+' more');return html};
ICONS.settings='<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>';
solidPaths.share='<path d="m12 2-6 6h4v8h4V8h4ZM3 13h3v6h12v-6h3v9H3Z"/>';
solidPaths.repost='<path d="M5 5h10V2l7 5-7 5V9H5Zm14 14H9v3l-7-5 7-5v3h10Z"/>';

const fullInvoiceEcosystem=fullInvoiceForm;
fullInvoiceForm=function(fromCard=false){fullInvoiceEcosystem(fromCard);const company=ecosystem.myBusinesses.find(b=>b.id===officeProject?.business&&b.canManage);if(company){for(const [key,value] of Object.entries({...company.billing,name:company.billing?.name||company.name})){const el=document.getElementById('inv-supplier-'+key);if(el)el.value=value||''}}};
const landingUniformCTA=renderLanding;
renderLanding=function(){const doc=new DOMParser().parseFromString(landingUniformCTA(),'text/html');doc.querySelectorAll('a[href^="/signup"],a[href^="/login"]').forEach(a=>{a.setAttribute('aria-label',a.href.includes('kind=fan')?'Tap in as a fan':'Tap in to TAPPED IN');a.textContent='TAP IN'});return doc.body.innerHTML};
